import data from "./timeline.json";
import { VIDEO } from "./brand";

// Single source of truth for timing: generated by scripts/build_audio.py together with the
// soundtrack, so every cut, hit and word on screen lines up with the audio.

export type Word = { text: string; start: number; end: number };
export type SceneId = "hook" | "brand" | "group" | "transformation" | "cta";

export const TIMELINE = data as {
  fps: number;
  durationSeconds: number;
  bpm: number;
  scenes: { id: SceneId; start: number; end: number }[];
  endCardAt: number;
  finalHit: number;
  hits: Record<"hookSlam" | "logo" | "groupDrop" | "breakdown" | "drop", number>;
  voLines: { id: SceneId; start: number; end: number; text: string }[];
  words: Word[];
};

export const sec = (s: number) => Math.round(s * VIDEO.fps);

export const DURATION_FRAMES = sec(TIMELINE.durationSeconds);

export const scene = (id: SceneId) => {
  const s = TIMELINE.scenes.find((x) => x.id === id);
  if (!s) throw new Error(`Unknown scene ${id}`);
  return { from: sec(s.start), duration: sec(s.end) - sec(s.start), start: s.start, end: s.end };
};

/** Start time (seconds) of the n-th occurrence of a spoken word, for syncing on-screen type to the VO. */
export const wordAt = (text: string, occurrence = 0) => {
  const hits = TIMELINE.words.filter((w) => w.text.replace(/[،.…!]/g, "") === text);
  if (!hits[occurrence]) throw new Error(`Word "${text}" #${occurrence} not in VO timeline`);
  return hits[occurrence].start;
};

/** Seconds → frames relative to the start of a scene. */
export const local = (id: SceneId, seconds: number) => sec(seconds) - scene(id).from;
